typeSystemExample.source:
fn max<T: PartialOrd>(a: T, b: T) -> T {
    if a >= b { a } else { b }
}

fn main() {
    println!("{}", max(3, 7));
    println!("{}", max(1.5, 2.8));
}

concurrencyExample.source:
use std::thread;

fn main() {
    let handles: Vec<_> = (0..4)
        .map(|i| thread::spawn(move || i * i))
        .collect();

    for h in handles {
        print!("{} ", h.join().unwrap());
    }
}
